# Glossaire J80 — Syndrome de détresse respiratoire aiguë et œdème pulmonaire (P-02-Pneumologie)
from cardio_1 import a, G
a('PEP',[('P','Pression'),('E','Expiratoire'),('P','Positive')],'Pression expiratoire positive','<p>Pression maintenue dans les voies aériennes en fin d’expiration par le ventilateur ou la VNI. Elle garde ouvertes les alvéoles instables et réduit le shunt ; une valeur excessive distend le poumon et diminue le retour veineux. Équivalent anglais : PEEP.</p>','j80-pep')
a('ARDS',[('A','Acute'),('R','Respiratory'),('D','Distress'),('S','Syndrome')],'Acute respiratory distress syndrome (syndrome de détresse respiratoire aiguë)','<p>Terme anglais du SDRA, employé dans les noms d’essais et de réseaux de recherche (ARDS Network).</p>','j80-global')
a('TRALI',[('T','Transfusion-'),('R','Related'),('A','Acute'),('L','Lung'),('I','Injury')],'Transfusion-related acute lung injury (lésion pulmonaire aiguë liée à la transfusion)','<p>Œdème pulmonaire de perméabilité survenant pendant une transfusion ou dans les six heures, causé surtout par des anticorps anti-HLA ou anti-HNA du donneur.</p>','j80-transfu')
a('TACO',[('T','Transfusion-'),('A','Associated'),('C','Circulatory'),('O','Overload')],'Transfusion-associated circulatory overload (surcharge circulatoire liée à la transfusion)','<p>Œdème pulmonaire hydrostatique par surcharge de volume transfusionnelle, dans les 12 heures ; hypertension et peptides natriurétiques élevés ; répond au diurétique.</p>','j80-transfu')
a('HNA',[('H','Human'),('N','Neutrophil'),('A','Antigen')],'Human neutrophil antigen (antigène des neutrophiles humains)','<p>Antigènes de surface des polynucléaires neutrophiles ; les anticorps dirigés contre eux, présents chez certains donneurs, peuvent provoquer un TRALI.</p>','j80-transfu')
a('PALICC',[('P','Pediatric'),('A','Acute'),('L','Lung'),('I','Injury'),('C','Consensus'),('C','Conference')],'Pediatric Acute Lung Injury Consensus Conference (conférence de consensus sur la lésion pulmonaire aiguë de l’enfant)','<p>Conférence qui définit le SDRA de l’enfant par l’indice d’oxygénation et l’indice de saturation ; éditions 2015 et 2023.</p>','j80-palicc')
a('PALICC-2',[('P','Pediatric'),('A','Acute'),('L','Lung'),('I','Injury'),('C','Consensus'),('C','Conference'),('-2','deuxième édition')],'Deuxième conférence de consensus sur la lésion pulmonaire aiguë de l’enfant (2023)','<p>Mise à jour publiée en 2023 dans Pediatric Critical Care Medicine.</p>','j80-palicc')
a('ROX',[('R','Respiratory rate (fréquence respiratoire)'),('O','Oxygenation (oxygénation)'),('X','indeX (indice)')],'Indice ROX (rapport SpO₂/FiO₂ divisé par la fréquence respiratoire)','<p>Indice proposé par Roca pour prédire le succès ou l’échec de l’oxygène nasal à haut débit ; ≥ 4,88 prédit le succès. Développement non strictement lettre à lettre : le X provient de « index ».</p>','j80-rox')
a('LUNG SAFE',[('LUNG','Large observational study to UNderstand the Global impact of'),('SAFE','Severe Acute respiratory FailurE')],'Étude LUNG SAFE (2014, publiée en 2016)','<p>Étude observationnelle internationale de 459 unités de soins intensifs dans 50 pays sur l’épidémiologie et la prise en charge du SDRA. Nom d’étude non strictement lettre à lettre.</p>','j80-lungsafe')
a('ARMA',[('ARMA','nom de l’essai de l’ARDS Network sur le volume courant (« Respiratory Management in Acute lung injury », acronyme non strictement lettre à lettre)')],'Essai ARMA (ARDS Network, 2000)','<p>Essai de 861 patients comparant 6 et 12 mL/kg de poids prédit ; mortalité 31,0 % contre 39,8 %.</p>','j80-arma')
a('PROSEVA',[('PRO','PROne positioning (décubitus ventral)'),('SEVA','in SEVere ARDS (dans le SDRA sévère)')],'Essai PROSEVA (2013)','<p>Essai de 466 patients : décubitus ventral d’au moins 16 heures dans le SDRA avec PaO₂/FiO₂ &lt; 150 ; mortalité à 28 jours 16,0 % contre 32,8 %. Acronyme non strictement lettre à lettre.</p>','j80-dv')
a('ACURASYS',[('ACURA','ACUte Respiratory distress syndrome (SDRA)'),('SYS','SYStematic paralysis (curarisation systématique)')],'Essai ACURASYS (2010)','<p>Essai de 340 patients : cisatracurium pendant 48 heures dans le SDRA avec PaO₂/FiO₂ &lt; 150. Acronyme non strictement lettre à lettre.</p>','j80-curares')
a('EOLIA',[('E','ECMO to rescue'),('O','(sauvetage par ECMO)'),('LIA','Lung Injury in severe ARDS')],'Essai EOLIA (2018)','<p>Essai de l’ECMO veino-veineuse précoce dans le SDRA très sévère ; mortalité à 60 jours 35 % contre 46 %, différence non significative. Acronyme non strictement lettre à lettre.</p>','j80-ecmo')
a('FACTT',[('F','Fluid'),('A','And'),('C','Catheter'),('T','Treatment'),('T','Trial')],'Essai FACTT (ARDS Network, 2006)','<p>Essai de 1 000 patients comparant une stratégie liquidienne conservatrice et libérale, et deux cathéters de surveillance.</p>','j80-liquides')
a('ART',[('A','Alveolar'),('R','Recruitment'),('T','Trial')],'Essai ART (Alveolar Recruitment Trial, 2017)','<p>Essai brésilien de 1 010 patients : la stratégie de recrutement alvéolaire avec titration de la PEP a augmenté la mortalité.</p>','j80-recrut')
a('DEXA-ARDS',[('DEXA','DEXAméthasone'),('ARDS','Acute Respiratory Distress Syndrome')],'Essai DEXA-ARDS (2020)','<p>Essai espagnol de 277 patients atteints de SDRA modéré à sévère : dexaméthasone 20 mg puis 10 mg par jour ; mortalité à 60 jours 21 % contre 36 %.</p>','j80-d-dexa')
a('FLORALI',[('FLORALI','nom d’essai (« High-FLOw oxygen thErapy in Resuscitation of patients with Acute Lung Injury »), non strictement lettre à lettre')],'Essai FLORALI (2015)','<p>Essai comparant oxygène nasal à haut débit, oxygène standard et VNI chez des patients hypoxémiques non hypercapniques.</p>','j80-hfno')
a('Diniz-Silva',[('Diniz-Silva','nom propre d’auteur')],'Diniz-Silva F. (auteur)','<p>Premier auteur d’une synthèse comparant les recommandations ESICM 2023 et ATS 2024 (Critical Care Science 2025).</p>')
a('J80.0',[('J80.0','code CIM-10-GM')],'Syndrome de détresse respiratoire aiguë de l’enfant, de l’adolescent et de l’adulte','<p>Sous-catégorie qui exige un cinquième caractère de gravité.</p>','j80-cim')
a('J80.01',[('J80.01','code CIM-10-GM')],'SDRA léger de l’adulte','<p>PaO₂/FiO₂ &gt; 200 et ≤ 300 mmHg avec PEP ≥ 5 cm H₂O (Berlin).</p>','j80-cim')
a('J80.02',[('J80.02','code CIM-10-GM')],'SDRA modéré de l’adulte','<p>PaO₂/FiO₂ &gt; 100 et ≤ 200 mmHg avec PEP ≥ 5 cm H₂O.</p>','j80-cim')
a('J80.03',[('J80.03','code CIM-10-GM')],'SDRA sévère de l’adulte','<p>PaO₂/FiO₂ ≤ 100 mmHg avec PEP ≥ 5 cm H₂O.</p>','j80-cim')
a('J80.04',[('J80.04','code CIM-10-GM')],'SDRA léger de l’enfant et de l’adolescent','<p>Indice d’oxygénation 4 à &lt; 8 ou indice de saturation 5 à &lt; 7,5.</p>','j80-cim')
a('J80.05',[('J80.05','code CIM-10-GM')],'SDRA modéré de l’enfant et de l’adolescent','<p>Indice d’oxygénation 8 à &lt; 16 ou indice de saturation 7,5 à &lt; 12,3.</p>','j80-cim')
a('J80.06',[('J80.06','code CIM-10-GM')],'SDRA sévère de l’enfant et de l’adolescent','<p>Indice d’oxygénation ≥ 16 ou indice de saturation ≥ 12,3.</p>','j80-cim')
a('J80.09',[('J80.09','code CIM-10-GM')],'SDRA sans précision du degré de gravité','<p>Code adapté lorsque le grade de Berlin ou de PALICC n’est pas documenté, par exemple chez le patient non intubé sous haut débit seul.</p>','j80-cim')
a('J18.2',[('J18.2','code CIM-10-GM')],'Pneumonie hypostatique, sans précision','<p>Exclue de J81 ; voir le cours J18.</p>')
a('J68.1',[('J68.1','code CIM-10-GM')],'Œdème pulmonaire dû à des produits chimiques, gaz, fumées et vapeurs','<p>Exclu de J81 : l’œdème toxique d’inhalation est codé ici.</p>')
a('P22.0',[('P22.0','code CIM-10-GM')],'Syndrome de détresse respiratoire du nouveau-né','<p>Maladie des membranes hyalines du nouveau-né, due à un déficit en surfactant ; exclue de J80.</p>')
a('T70.2',[('T70.2','code CIM-10-GM')],'Effets autres et non précisés de la haute altitude','<p>Code des atteintes liées à l’altitude (mal aigu des montagnes, œdèmes de haute altitude), associé à J81 pour décrire l’œdème pulmonaire.</p>','j80-hape')
